contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(this), address(this)); }
    function testRegression_property() public {
        c.addReward(address(0xdead));
        bool ok;
        vm.prank(address(this));
        try c.setRewardDistributor(address(0x1234)) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(c.rewardDistributor() == address(0x1234));
    }
}
